vendor_correlations.combined_query:
// APT29 PowerShell + Network Correlation (88% semantic overlap)
let powershell_events = (
    DeviceProcessEvents
    | where Timestamp > ago(1d)
    | where FileName =~ "powershell.exe"
    | where ProcessCommandLine has_any ("-enc", "-encodedcommand")
    | project Timestamp, DeviceId, DeviceName, AccountName, ProcessId
);
let network_events = (
    DeviceNetworkEvents
    | where Timestamp > ago(1d)
    | where RemoteIPType == "Public"
    | where RemotePort in (443, 8443, 4443)
    | project Timestamp, DeviceId, DeviceName, RemoteIP, RemotePort
);
union powershell_events, network_events
| summarize EventCount = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp) by DeviceId, DeviceName
| where EventCount >= 2
| extend TimeSpan = datetime_diff('minute', LastSeen, FirstSeen)
| where TimeSpan <= 60

